定 Mock/replay 样本未找到该资产、本次未完成关联告警查询，不能把资产查询失败写成没有告警或真实 SOC 不存在该资产。保留真实失败回执，不执行写入。"},"output_contract":{"exact_keys":["verdict","reason","requirements"],"requirements":[{"requirement":"逐字复制对应要求，保持顺序且不遗漏","status":"satisfied | failed | unknown","evidence":[{"index":"显式选择 citation_allowed 为 true 的 indexed_evidence 整数索引，从 0 开始"}]}],"verdict":["passed","failed","inconclusive"],"reason":"non-empty zh-CN string"}}

